#[inductive(combiner_go_to_responding)]
fn combiner_go_to_responding_inductive(pre: Self, post: Self) {
    // The transition only changes the combiner field
    // All other fields remain the same
    assert(pre.num_clients == post.num_clients);
    assert(pre.clients =~= post.clients);
    assert(pre.slots =~= post.slots);
    assert(pre.requests =~= post.requests);
    assert(pre.responses =~= post.responses);

    // Since all relevant fields are unchanged, the invariants hold:
    // not_waiting_inv: forall i, if client i is Idle then slot i is false
    assert(forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() ==>
        !post.slots.index(i)) by {
            assert(pre.valid_idx(i) && pre.clients.index(i).is_Idle() ==> !pre.slots.index(i));
    };

    // waiting_inv: forall i, if client i is Waiting then request/response stored or combiner has it
    assert(forall |i: nat| #[trigger] post.client_waiting(i) ==>
        post.request_stored(i) || post.response_stored(i) || post.combiner_has(i)) by {
            assert(pre.client_waiting(i) ==> pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i));
            // Need to check combiner_has specifically since combiner changed
            if pre.client_waiting(i) {
                assert(pre.combiner.is_Collecting());
                let elems = pre.combiner.get_Collecting_elems();
                if i < elems.len() && elems.index(i as int).is_Some() {
                    // In pre-state, combiner had it
                    assert(post.combiner_has(i));
                }
            }
    };
}

