                assert(elems =~= post_elems);
                // And i >= post_idx (which is 0) because i < elems.len()
                assert(i >= post_idx);
                assert(post.combiner_has(i));
            }

            assert(post.request_stored(i) || post.response_stored(i) || post.combiner_has(i));
        }
    };
}

