        implies !post.slots.index(i) by {
        // Fields other than combiner are unchanged
        assert(pre.valid_idx(i) && pre.clients.index(i).is_Idle() ==> !pre.slots.index(i));
        assert(post.slots.index(i) == pre.slots.index(i));
    };

    // waiting_inv preservation: forall i: nat, client_waiting(i) ==> request_stored(i) || response_stored(i) || combiner_has(i)
    assert forall |i: nat| #[trigger] post.client_waiting(i) 
        implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
        // client_waiting depends only on clients and valid_idx which are unchanged
        assert(pre.client_waiting(i));

        // The predicates request_stored, response_stored are unchanged
        assert(post.request_stored(i) == pre.request_stored(i));
        assert(post.response_stored(i) == pre.response_stored(i));

        // For combiner_has: we need to consider the change from Collecting to Responding
        if pre.combiner_has(i) {
            // Pre-condition: i < pre_elems.len() && pre_elems[i].is_Some()
            assert(i < pre_elems.len());
            assert(pre_elems.index(i as int).is_Some());

            // Post-condition: i >= 0 (post_idx) && post_elems[i].is_Some()
            // Since post_elems == pre_elems and post_idx == 0
            assert(post.combiner_has(i));
        }

        assert(pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i) ==>
               post.request_stored(i) || post.response_stored(i) || post.combiner_has(i));
    };

    // request_stored_inv preservation: forall i: nat, request_stored(i) ==> client_waiting(i) && requests[i].rid == clients[i].Waiting.rid && slots[i]
    assert forall |i: nat| #[trigger] post.request_stored(i) implies 
        post.client_waiting(i) 
        && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid() 
        && post.slots.index(i) by {
        // Since requests, clients, and slots are unchanged
        assert(pre.request_stored(i));
        assert(pre.client_waiting(i));
        assert(pre.requests.index(i).rid == pre.clients.index(i).get_Waiting_rid());
        assert(pre.slots.index(i));

        assert(post.client_waiting(i) == pre.client_waiting(i));
        assert(post.requests.index(i).rid == pre.requests.index(i).rid);
        assert(post.clients.index(i).get_Waiting_rid() == pre.clients.index(i).get_Waiting_rid());
        assert(post.slots.index(i) == pre.slots.index(i));
    };

    // response_stored_inv preservation: forall i: nat, response_stored(i) ==> client_waiting(i) && responses[i].rid == clients[i].Waiting.rid && !slots[i]
    assert forall |i: nat| #[trigger] post.response_stored(i) implies 
        post.client_waiting(i) 
        && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid() 
        && !post.slots.index(i) by {
        // Since responses, clients, and slots are unchanged
        assert(pre.response_stored(i));
        assert(pre.client_waiting(i));
        assert(pre.responses.index(i).rid == pre.clients.index(i).get_Waiting_rid());
        assert(!pre.slots.index(i));

        assert(post.client_waiting(i) == pre.client_waiting(i));
        assert(post.responses.index(i).rid == pre.responses.index(i).rid);
        assert(post.clients.index(i).get_Waiting_rid() == pre.clients.index(i).get_Waiting_rid());
        assert(post.slots.index(i) == pre.slots.index(i));
    };

    // combiner_has_inv preservation: forall i: nat, combiner_has(i) ==> client_waiting(i) && slots[i] && combiner_rid(i) == clients[i].Waiting.rid && !request_stored(i)
    assert forall |i: nat| #[trigger] post.combiner_has(i) implies 
        post.client_waiting(i) 
        && post.slots.index(i)
        && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
        && !post.request_stored(i) by {
        // If post.combiner_has(i), then in post-state combiner is Responding and i >= idx (=0) && elems[i].is_Some
        assert(post.combiner.is_Responding());
        let post_elems = post.combiner.get_Responding_elems();
        let post_idx = post.combiner.get_Responding_idx();
        assert(post_idx == 0);
        assert(i >= post_idx);
        assert(post_elems.index(i as int).is_Some());

        // This means in pre-state, combiner was Collecting and i < elems.len() && elems[i].is_Some
        assert(pre.combiner_has(i));
        assert(pre.combiner.is_Collecting());
        let pre_elems = pre.combiner.get_Collecting_elems();
        assert(i < pre_elems.len());
        assert(pre_elems.index(i as int).is_Some());

        // So pre.combiner_has(i), and all the pre-conditions hold
        assert(pre.client_waiting(i));
        assert(pre.slots.index(i));
        assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
        assert(!pre.request_stored(i));

        // Since clients, slots, requests unchanged
        assert(post.client_waiting(i) == pre.client_waiting(i));
        assert(post.slots.index(i) == pre.slots.index(i));
        assert(!post.request_stored(i) == !pre.request_stored(i));

        // Need to show combiner_rid equality is preserved
        assert(post.combiner_rid(i) == pre.combiner_rid(i));
        assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
        assert(post.clients.index(i).get_Waiting_rid() == pre.clients.index(i).get_Waiting_rid());
        assert(post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid());
    };
}

