fn combiner_go_to_responding_inductive(pre: Self, post: Self) {
    // The transition only changes the combiner field
    // All other fields remain the same
    assert(pre.num_clients == post.num_clients);
    assert(pre.clients =~= post.clients);
    assert(pre.slots =~= post.slots);
