        assert(pre.valid_idx(i) && pre.clients.index(i).is_Idle() ==> !pre.slots.index(i));
        assert(post.slots.index(i) == pre.slots.index(i));
    }

    // waiting_inv preservation: forall i: nat, client_waiting(i) ==> request_stored(i) || response_stored(i) || combiner_has(i)
    assert forall |i: nat| #[trigger] post.client_waiting(i) 
        implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
        // client_waiting depends only on clients and valid_idx which are unchanged
        assert(pre.client_waiting(i));

        // The predicates request_stored, response_stored are unchanged
        assert(post.request_stored(i) == pre.request_stored(i));
        assert(post.response_stored(i) == pre.response_stored(i));

        // For combiner_has: we need to consider the change from Collecting to Responding
        if pre.combiner_has(i) {
            // Pre-condition: i < pre_elems.len() && pre_elems[i].is_Some()
            assert(i < pre_elems.len());
            assert(pre_elems.index(i as int).is_Some());

            // Post-condition: i >= 0 (post_idx) && post_elems[i].is_Some()
